def transform(grid):
    g = np.array(grid)
    bg = background(g)
    groups = {}
    for y, x in zip(*np.nonzero(g != bg)):
        groups.setdefault(int(g[y, x]), []).append((int(y), int(x)))
    boxes = {c: bbox(cells) for c, cells in groups.items()}
    H = max(b[2] - b[0] + 1 for b in boxes.values())
    W = max(b[3] - b[1] + 1 for b in boxes.values())
    out = np.full((H, W), bg, dtype=int)
    emit(out, f"Allocate a {H}x{W} canvas of background {bg}: the size of the largest four-point figure.")
    order = sorted(groups, key=lambda c: -((boxes[c][2]-boxes[c][0]+1)*(boxes[c][3]-boxes[c][1]+1)))
    for c in order:
        y0, x0, y1, x1 = boxes[c]
        h, w = y1 - y0 + 1, x1 - x0 + 1
        oy, ox = (H - h) // 2, (W - w) // 2
        for y, x in groups[c]:
            out[y - y0 + oy, x - x0 + ox] = c
        emit(out, f"Stamp the colour-{c} figure ({h}x{w}) centred on the canvas, keeping its shape.")
    return out
